impl Logger {
    fn new(min_level: LogLevel) -> Result<Self, Error> {
        let log_dir = dirs::data_dir()
            .ok_or_else(|| Error::DataDirNotFound)?
            .join("dotdot")
            .join("logs");

        std::fs::create_dir_all(&log_dir)?;

        let log_file_name = format!("{}.log", Utc::now().format("%Y-%m-%d"));
        let log_path = log_dir.join(log_file_name);

        Ok(Self {
            log_path,
            min_level,
            buffer: Vec::new(),
            buffer_size: 100
        })
    }

    fn log(&mut self, level: LogLevel, component: &str, message: &str, details: Option<serde_json::Value>, session_id: Option<Uuid>) -> Result<(), Error> {
        if level < self.min_level {
            return Ok(());
        }

        let entry = LogEntry {
            timestamp: Utc::now(),
            level,
            component: component.to_string(),
            message: message.to_string(),
            details,
            session_id
        };

        self.buffer.push(entry.clone());

        if self.buffer.len() >= self.buffer_size {
            self.flush()?;
        }

        Ok(())
    }

    fn flush(&mut self) -> Result<(), Error> {
        if self.buffer.is_empty() {
            return Ok(());
        }

        let mut file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.log_path)?;

        for entry in &self.buffer {
            let entry_json = serde_json::to_string(entry)?;
            writeln!(file, "{}", entry_json)?;
        }

        self.buffer.clear();

        Ok(())
    }

